import{z as n,x as i,o as t,c as o,q as e,j as B,D as E,d as A,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"静态时序分析 STA","description":"","frontmatter":{"title":"静态时序分析 STA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sta.md","filePath":"cs/sta.md","lastUpdated":1791413859000}'),d={name:"cs/sta.md"};function F(p,a,C,c,T,_){const s=i("Mermaid");return t(),o("div",null,[a[2]||(a[2]=e('<h1 id="静态时序分析-sta" tabindex="-1">静态时序分析 STA <a class="header-anchor" href="#静态时序分析-sta" aria-label="Permalink to &quot;静态时序分析 STA&quot;">​</a></h1><div class="epigraph"><p>不必穷举向量：把组合路径的最大/最小延迟加起来，对照建立与保持不等式，就能判定这张网表在给定周期下是否违例。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/synthesis-netlist">上一课</a>交出网表。组成课已有<a href="/cs/setup-hold">建立保持</a>不等式。缺口是工程上的<strong>静态时序分析</strong>：在所有（或约束声明的）寄存器到寄存器路径上检查建立/保持，而不是靠仿真碰巧打到关键路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>功能仿真再久也覆盖不了指数级输入。时序是另一类性质：路径延迟是否 ≤ 周期预算。STA：图上节点是引脚，边是单元延迟与线延迟（先用线负载模型，布局后再用提取寄生）。缺口不是再定义 \\(t_{su}\\)，而是：<strong>时序弧、时钟定义、伪路径、多周期路径</strong>如何让分析与设计意图一致。</p><p>建立用最大延迟（慢角、晚时钟），保持用最小延迟（快角、早时钟）。与后课偏斜/CTS 衔接：时钟到达时间进入同一组不等式。</p><h3 id="sta-不是「证明功能正确」" tabindex="-1">STA 不是「证明功能正确」 <a class="header-anchor" href="#sta-不是「证明功能正确」" aria-label="Permalink to &quot;STA 不是「证明功能正确」&quot;">​</a></h3><p>全 0 的网表可以时序干净。功能靠仿真、断言与后课等价检查。把 STA 通过当成芯片功能签核，算术单元的饱和 MUX 接错也看不见。</p><p><span class="marginnote">Harris 把时序分析接到建立保持。CA:AQA 从周期与 CPI 看时钟。工业 SDC 是约束语言，本课用它的概念不背命令全集。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>声明时钟周期与波形。2. 输入/输出延迟相对该时钟。3. 工具枚举 FF→组合→FF 路径，报告 slack。4. 假路径（异步输入未同步前）必须声明，否则误报。5. 多周期路径（除法器迭代）放宽建立。保持通常仍是单周期关系。<span class="marginnote">术语翻译：slack 就是「预算减实耗」的余量——建立 \\(\\text{slack} = T - t_{cq} - t_{pd,\\max} - t_{su}\\)，负数即违例，绝对值就是这条路径还差多少纳秒；整张报告就是按它排序的欠账单。</span></li></ol>',11)),(t(),B(l,null,{default:E(()=>[r(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20NL%5B%22%E7%BD%91%E8%A1%A8%20%2B%20%E5%BA%93%E5%BB%B6%E8%BF%9F%22%5D%20--%3E%20STA%5B%22%E8%B7%AF%E5%BE%84%E6%9E%9A%E4%B8%BE%22%5D%0A%20%20SDC%5B%22%E6%97%B6%E9%92%9F%E4%B8%8E%E4%BE%8B%E5%A4%96%22%5D%20--%3E%20STA%0A%20%20STA%20--%3E%20SLACK%5B%22%E5%BB%BA%E7%AB%8B%2F%E4%BF%9D%E6%8C%81%20slack%22%5D%0A%20%20SLACK%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%81%8F%E6%96%9C%E4%B8%8E%E6%97%B6%E9%92%9F%E6%A0%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p>与<a href="/cs/critical-path">关键路径</a>课对照：组成课画数据通路最长组合；STA 在真实库上把那条路径量化成 ns。<span class="marginnote">直觉类比：声明伪路径像告诉体检机构「这两项指标之间没有因果关系，别连着判」——异步输入未同步前那条路不构成有效的同步传输，不声明就会收到一堆无意义的违例报告，把真违例淹没。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>负 slack → 降频、改 RTL、换快单元、或后课物理设计缩短线。保持违例降频无效——与建立保持课同一句。跨时钟域路径默认不该当同步路径分析，下一课之后的 FIFO 才是合法结构；错误地用 STA「对两个无关时钟做建立检查」会产生无意义违例或虚假通过。<span class="marginnote">常见误区：以为保持违例也能靠降频解决。保持检查比的是同一时钟沿前后数据的最小延迟，与时钟周期 \\(T\\) 无关——降频改不了它，唯一的修法是在快路径上垫延迟单元，让数据别跑得太快。</span></p>',3)),(t(),B(l,null,{default:E(()=>[r(s,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLK%5B%22%E6%97%B6%E9%92%9F%E5%91%A8%E6%9C%9F%20T%22%5D%20--%3E%20SU%5B%22%E5%BB%BA%E7%AB%8B%E6%A3%80%E6%9F%A5%EF%BC%9A%E6%85%A2%E8%A7%92%EF%BC%8C%E6%9C%80%E5%A4%A7%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20SU%20--%3E%20INEQ%5B%22%E6%AF%94%E8%BE%83%EF%BC%9A%E8%B7%AF%E5%BE%84%E5%BB%B6%E8%BF%9F%E4%B8%8E%E9%A2%84%E7%AE%97%20T%22%5D%0A%20%20INEQ%20--%3E%20NEG%7B%22%E5%BB%BA%E7%AB%8B%20slack%20%E9%9D%9E%E8%B4%9F%EF%BC%9F%22%7D%0A%20%20NEG%20--%3E%7C%22%E5%90%A6%22%7C%20FIX%5B%22%E9%99%8D%E9%A2%91%E3%80%81%E6%94%B9%20RTL%E3%80%81%E6%8D%A2%E5%BF%AB%E5%8D%95%E5%85%83%22%5D%0A%20%20CLK%20--%3E%20HD%5B%22%E4%BF%9D%E6%8C%81%E6%A3%80%E6%9F%A5%EF%BC%9A%E5%BF%AB%E8%A7%92%EF%BC%8C%E6%9C%80%E5%B0%8F%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20HD%20--%3E%20INE2%5B%22%E6%AF%94%E8%BE%83%EF%BC%9A%E6%9C%80%E5%B0%8F%E5%BB%B6%E8%BF%9F%E4%B8%8E%E4%BF%9D%E6%8C%81%E7%AA%97%E5%8F%A3%22%5D%0A%20%20INE2%20--%3E%20NEGH%7B%22%E4%BF%9D%E6%8C%81%E8%BF%9D%E4%BE%8B%EF%BC%9F%22%7D%0A%20%20NEGH%20--%3E%7C%22%E6%98%AF%22%7C%20FIXH%5B%22%E5%9E%AB%E5%BB%B6%E8%BF%9F%E5%8D%95%E5%85%83%EF%BC%8C%E9%99%8D%E9%A2%91%E6%97%A0%E6%95%88%22%5D%0A%20%20NEGH%20--%3E%7C%22%E5%90%A6%22%7C%20PASS%5B%22%E8%AF%A5%E9%A1%B9%E9%80%9A%E8%BF%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲统计时序（SSTA）的全部相关模型，不把电源噪声时序（SI）写完。不引入光刻 OPC 对延迟的影响——那是光刻栏。也不把 GPU 训练迭代当时序向量。</p><p>后课默认：周期约束下的建立/保持由 STA 在网表上检查；时钟到达时间的差异是下一课 CTS 的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STA 静态累加路径延迟，对照 \\(t_{su}\\)/\\(t_h\\)。</li><li>不替代功能验证。</li><li>假路径与多周期必须声明，否则分析与意图分裂。</li><li>出处：Harris and Harris；Hennessy and Patterson, CA:AQA。</li></ul>',5))])}const D=n(d,[["render",F]]);export{S as __pageData,D as default};
